 public static string Run(string mode){
  if(mode!="capture"&&mode!="wheel-down"&&mode!="wheel-up"&&mode!="hover-up"&&mode!="hover-down"&&mode!="hover-thumb"&&mode!="arrow-down"&&mode!="drag-bottom"&&mode!="pressed-thumb"&&mode!="pressed-arrow"&&mode!="pressed-up"&&mode!="arrow-up"&&mode!="hold-pause"&&mode!="hold-detach"&&mode!="track-below"&&mode!="hold-down"&&mode!="reset"&&mode!="body-click"&&mode!="arrow-down-key"&&mode!="page-down-key"&&mode!="home-key"&&mode!="end-key"&&mode!="page-tall"&&mode!="wheel-burst"&&mode!="child-tab"&&mode!="short-key"&&mode!="detach-pending"&&mode!="interrupt-shrink"&&mode!="tab-back"&&mode!="space-key"&&mode!="shift-space-key"&&mode!="wheel-reverse")throw new InvalidOperationException("Fixed scroll source mode required");
